{"cell_index": 18, "code": "from torch.nn.utils.rnn import pad_sequence

def collate_fn(batch):
    # batch is a list of tuples (x, y)
    xs = [item[0] for item in batch]
    ys = [item[1] for item in batch]

    # Pad sequences to the same length
    xs_padded = pad_sequence(xs, batch_first=True, padding_value=0)
    ys_tensor = torch.tensor(ys)

    return xs_padded, ys_tensor

class sentimentdata(Dataset):
    def __init__(self , X,Y ):
        self.X = X
        self.Y = Y
    def __len__(self):
        return len(self.X)
    def __getitem__(self , index):
        x = self.X[index]
        y= self.Y[index]

        return x,y

st_train_loader = sentimentdata(X ,ylb)
