{"cell_index": 18, "code": "# Custom collate function to handle single-item batches
def collate_single(batch):
    # With batch_size=1, batch is just a single tuple (x, y)
    # We need to make x shape [1, seq_len] and y shape [1]
    x, y = batch[0]
    x = x.unsqueeze(0)  # Add batch dimension
    y = torch.tensor([y])  # Make y a tensor
    return x, y

class sentimentdata(Dataset):
    def __init__(self , X,Y ):
        self.X = X
        self.Y = Y
    def __len__(self):
        return len(self.X)
    def __getitem__(self , index):
        x = self.X[index]
        y= self.Y[index]

        return x,y

st_train_loader = sentimentdata(X ,ylb)
st_test_loader = sentimentdata(X ,ytb)

